import dataclasses
import re

import pytest

from solift import ops
from solift.ir import UINT256, Const, Function, Model, Read, Return, Var
from solift.link import Check, LinkError, generate, operators_test
from solift.solidity import source
from tests.models import quote
from tests.projects import QUOTER_LINK

LINK_TEST = """\
// SPDX-License-Identifier: Apache-2.0
// Generated by solift: the link of Quoter._quote to its model. Do not edit.
pragma solidity ^0.8.27;

import {QuoterSetup} from "tests/fixtures/test/QuoterSetup.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {QuoterQuoteModel, QuoterQuoteHost} from "./QuoterQuote.sol";

contract QuoterQuoteLink is QuoterSetup {
  function check_link(
    uint256 _gas,
    uint256 _price,
    uint128 margin,
    uint128 cap,
    uint256 floor,
    uint256 pot,
    uint256 baseFee
  ) public {
    quoter.setConfig(margin, cap, floor);
    token.set(pot);
    vm.fee(baseFee);
    bytes memory codeOut;
    bytes memory modelOut;
    {
      QuoterQuoteModel.Inputs memory i = QuoterQuoteModel.Inputs({
        _gas: _gas,
        _price: _price,
        margin: margin,
        cap: cap,
        floor: floor,
        pot: pot,
        txGasPrice: tx.gasprice,
        baseFee: baseFee
      });
      bool codeOk;
      (codeOk, codeOut) = address(quoter).call(
        abi.encodeCall(quoter.exposedQuote, (_gas, _price))
      );
      QuoterQuoteHost host = new QuoterQuoteHost();
      bool modelOk;
      (modelOk, modelOut) = address(host).call(abi.encodeCall(host.run, (i)));
      assert(codeOk == modelOk);
      if (!codeOk) {
        return;
      }
    }
    assert(abi.decode(codeOut, (uint256)) == abi.decode(modelOut, (uint256)));
  }
}
"""


def test_the_link_test_sets_each_input_through_the_call_an_adapter_or_an_observed_value():
    generated = generate(quote(), QUOTER_LINK)
    assert generated.files["QuoterQuoteLink.t.sol"] == LINK_TEST


def test_the_run_declares_the_link_and_each_row_and_lemma_that_the_model_uses():
    generated = generate(quote(), QUOTER_LINK)
    assert set(generated.files) == {"QuoterQuote.sol", "QuoterQuoteLink.t.sol", "QuoterQuoteOperators.t.sol"}
    rows = {c.function for c in generated.checks if c.contract == "QuoterQuoteOperators"}
    assert rows == {
        "check_row_addRevertsExactlyOnOverflow",
        "check_lemma_minIsTheSmallerValue",
        "check_row_mulRevertsExactlyOnOverflow",
        "check_row_mulDivOfHalfWidthOperandsRevertsExactlyOnZero",
        "check_lemma_mulModOfHalfWidthOperandsIsTheProduct",
        "check_lemma_mulDivOfHalfWidthOperandsIsTheFloor",
        "check_row_subRevertsExactlyBelowZero",
    }
    assert Check("QuoterQuoteLink", "check_link", "QuoterQuoteLink.t.sol") in generated.checks
    operators = generated.files["QuoterQuoteOperators.t.sol"]
    assert 'import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";' in operators
    assert "function check_row_divRevertsExactlyOnZero" not in operators


@pytest.mark.parametrize(
    "change, message",
    [
        ({"adapters": {**QUOTER_LINK.adapters, "pot": "token.set(0);"}}, "does not use it"),
        ({"observed": {}}, "no call argument, adapter or observed value sets the input txGasPrice"),
        ({"observed": {"txGasPrice": "tx.gasprice", "baseFee": "block.basefee"}}, "sets baseFee twice"),
        ({"observed": {"txGasPrice": "tx.gasprice", "gasPrice": "tx.gasprice"}}, "gasPrice, which is not an input"),
        (
            {"call": "quoter.exposedQuote(_gas, 1)", "observed": {"txGasPrice": "tx.gasprice", "_price": "1"}},
            "must reach the contract through the call",
        ),
        ({"call": "exposedQuote(_gas)"}, "is not target.function"),
        ({"parameters": {"pot": "uint256"}}, "the link parameter pot has the name of an input"),
        ({"parameters": {"host": "uint256"}}, "host has a name that the generated test uses"),
        ({"parameters": {"modelResults": "uint256"}}, "modelResults has a name that the generated test uses"),
    ],
)
def test_a_link_that_does_not_set_each_input_exactly_once_is_refused(change, message):
    link = dataclasses.replace(QUOTER_LINK, **change)
    with pytest.raises(LinkError, match=message):
        generate(quote(), link)


def test_a_link_parameter_is_symbolic_and_sets_a_cut_point_that_the_test_observes():
    """The model of a quote whose second parameter is a cut point: the price that the contract computes from a feed."""
    model = quote()
    function = dataclasses.replace(model.function, params=model.function.params[:1])
    price = Read(Var("price", input=True), "_feedPrice()")
    model = dataclasses.replace(model, function=function, reads=(*model.reads, price))
    link = dataclasses.replace(
        QUOTER_LINK,
        call="quoter.quoteAtFeed(_gas)",
        adapters={**QUOTER_LINK.adapters, "answer": "feed.set(int256(uint256(answer)), block.timestamp);"},
        observed={"txGasPrice": "tx.gasprice", "price": "quoter.exposedFeedPrice()"},
        parameters={"answer": "uint128"},
        imports=('import {Quoter} from "src/Quoter.sol";',),
    )
    test = generate(model, link).files["QuoterQuoteLink.t.sol"]
    assert "    uint256 baseFee,\n    uint128 answer\n  ) public {" in test
    assert "    feed.set(int256(uint256(answer)), block.timestamp);\n" in test
    assert "      price: quoter.exposedFeedPrice()" in test
    assert 'import {Quoter} from "src/Quoter.sol";' in test


def _smaller(contract: str, math: str, imports: tuple[str, ...] = ()) -> Model:
    """`return Math.min(_a, _b) + 1;`, with Math from `math`."""
    a, b = Var("_a", input=True), Var("_b", input=True)
    body = (Return(ops.make("add", ops.make("min", a, b), Const(1))),)
    function = Function("smaller", (a, b), UINT256, body)
    return Model(contract, function, math=math, imports=imports, pragma="^0.8.27")


def test_each_copy_of_math_has_its_own_operators_test_and_the_other_rows_are_in_the_first():
    first, second = _smaller("A", "@first/utils/math/Math.sol"), _smaller("B", "@second/utils/math/Math.sol")
    generated = operators_test([first, second, _smaller("C", "@first/utils/math/Math.sol")], "Shared")
    assert {(c.path, c.contract, c.function) for c in generated.checks} == {
        ("SharedOperators.t.sol", "SharedOperators", "check_row_addRevertsExactlyOnOverflow"),
        ("SharedOperators.t.sol", "SharedOperators", "check_lemma_minIsTheSmallerValue"),
        ("Shared2Operators.t.sol", "Shared2Operators", "check_lemma_minIsTheSmallerValue"),
    }
    assert set(generated.files) == {"SharedOperators.t.sol", "Shared2Operators.t.sol"}
    one, two = generated.files["SharedOperators.t.sol"], generated.files["Shared2Operators.t.sol"]
    assert re.findall(r"^import \{Math\}.*", one, re.M) == ['import {Math} from "@first/utils/math/Math.sol";']
    assert re.findall(r"^import \{Math\}.*", two, re.M) == ['import {Math} from "@second/utils/math/Math.sol";']
    assert "the operator-table rows and lemmas that A.smaller, B.smaller, C.smaller uses" in one
    assert "the operator-table rows and lemmas that B.smaller uses" in two
    assert "contract Shared2CheckedOperators {" in two and "contract Shared2Operators is Test {" in two
    assert "function add(" in one and "function add(" not in two


def test_the_operators_test_imports_math_and_no_enum_of_a_model():
    """Two enums of one name from two files: the rows and lemmas need neither, so the test imports neither."""
    math = "@first/utils/math/Math.sol"
    models = [
        _smaller("A", math, ('import {Side} from "src/One.sol";',)),
        _smaller("B", math, ('import {Side} from "src/Two.sol";',)),
    ]
    (test,) = operators_test(models, "Shared").files.values()
    assert [line for line in test.splitlines() if line.startswith("import")] == [
        'import {Test} from "forge-std/Test.sol";',
        f'import {{Math}} from "{math}";',
    ]
    assert source(models[0]).startswith(
        "// SPDX-License-Identifier: UNLICENSED\n// Generated by solift from A.smaller. Do not edit.\n"
        f'pragma solidity ^0.8.27;\n\nimport {{Math}} from "{math}";\nimport {{Side}} from "src/One.sol";\n\n'
    )


@pytest.mark.parametrize(
    "solc, old", [("0.8.10", True), ("0.8.10+commit.fc410830", True), ("0.8.11", False), ("", False)]
)
def test_below_solc_0_8_11_the_generated_tests_call_by_selector(solc, old):
    """solc 0.8.10 and older have no abi.encodeCall: the link, the model's host call and the operator rows encode the
    selector and the arguments instead."""
    model = dataclasses.replace(quote(), solc=solc)
    generated = generate(model, QUOTER_LINK)
    text = "\n".join(generated.files.values())
    if old:
        assert "abi.encodeCall" not in text
        assert "abi.encodeWithSelector(quoter.exposedQuote.selector, _gas, _price)" in text
        assert "abi.encodeWithSelector(host.run.selector, i)" in text
        assert "abi.encodeWithSelector(ops.mul.selector, _a, _b)" in text
    else:
        assert "abi.encodeWithSelector" not in text
        assert "abi.encodeCall(host.run, (i))" in text
